module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg         valid_o,
    output reg  [15:0] y_o
);

    // Generate/propagate bits
    wire [15:0] p0, g0;
    assign p0 = a_i ^ b_i;
    assign g0 = a_i & b_i;

    // Kogge-Stone prefix network, distances 1,2,4,8
    wire [15:0] p1, g1;
    wire [15:0] p2, g2;
    wire [15:0] p3, g3;
    wire [15:0] p4, g4;

    genvar i;

    // Stage 1 : distance = 1
    generate
        for (i = 0; i < 16; i = i + 1) begin : STAGE1
            if (i >= 1) begin
                assign g1[i] = g0[i] | (p0[i] & g0[i-1]);
                assign p1[i] = p0[i] & p0[i-1];
            end else begin
                assign g1[i] = g0[i];
                assign p1[i] = p0[i];
            end
        end
    endgenerate

    // Stage 2 : distance = 2
    generate
        for (i = 0; i < 16; i = i + 1) begin : STAGE2
            if (i >= 2) begin
                assign g2[i] = g1[i] | (p1[i] & g1[i-2]);
                assign p2[i] = p1[i] & p1[i-2];
            end else begin
                assign g2[i] = g1[i];
                assign p2[i] = p1[i];
            end
        end
    endgenerate

    // Stage 3 : distance = 4
    generate
        for (i = 0; i < 16; i = i + 1) begin : STAGE3
            if (i >= 4) begin
                assign g3[i] = g2[i] | (p2[i] & g2[i-4]);
                assign p3[i] = p2[i] & p2[i-4];
            end else begin
                assign g3[i] = g2[i];
                assign p3[i] = p2[i];
            end
        end
    endgenerate

    // Stage 4 : distance = 8
    generate
        for (i = 0; i < 16; i = i + 1) begin : STAGE4
            if (i >= 8) begin
                assign g4[i] = g3[i] | (p3[i] & g3[i-8]);
                assign p4[i] = p3[i] & p3[i-8];
            end else begin
                assign g4[i] = g3[i];
                assign p4[i] = p3[i];
            end
        end
    endgenerate

    // Carries out of each bit position (cin = 0 for whole adder)
    wire [15:0] c;
    assign c = g4;

    // Final sum bits
    wire [15:0] sum;
    assign sum[0] = p0[0];
    generate
        for (i = 1; i < 16; i = i + 1) begin : SUMBITS
            assign sum[i] = p0[i] ^ c[i-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    // Level 0: per-bit hypothesis sum/carry assuming incoming carry 0 or 1
    wire [15:0] sum0_L0, sum1_L0, carry0_L0, carry1_L0;
    assign sum0_L0   = a_i ^ b_i;
    assign sum1_L0   = ~sum0_L0;
    assign carry0_L0 = a_i & b_i;
    assign carry1_L0 = a_i | b_i;

    // Level 1: combine size-1 blocks into size-2 blocks (8 blocks)
    wire [15:0] sum0_L1, sum1_L1;
    wire [7:0]  carry0_L1, carry1_L1;
    genvar j1;
    generate
        for (j1 = 0; j1 < 8; j1 = j1 + 1) begin : LVL1
            localparam integer LO = 2*j1;
            localparam integer HI = 2*j1 + 1;
            assign sum0_L1[LO] = sum0_L0[LO];
            assign sum1_L1[LO] = sum1_L0[LO];
            assign sum0_L1[HI] = carry0_L0[LO] ? sum1_L0[HI] : sum0_L0[HI];
            assign sum1_L1[HI] = carry1_L0[LO] ? sum1_L0[HI] : sum0_L0[HI];
            assign carry0_L1[j1] = carry0_L0[LO] ? carry1_L0[HI] : carry0_L0[HI];
            assign carry1_L1[j1] = carry1_L0[LO] ? carry1_L0[HI] : carry0_L0[HI];
        end
    endgenerate

    // Level 2: combine size-2 blocks into size-4 blocks (4 blocks)
    wire [15:0] sum0_L2, sum1_L2;
    wire [3:0]  carry0_L2, carry1_L2;
    genvar j2;
    generate
        for (j2 = 0; j2 < 4; j2 = j2 + 1) begin : LVL2
            localparam integer LOBLK = 2*j2;
            localparam integer HIBLK = 2*j2 + 1;
            localparam integer LO0 = 4*j2;
            localparam integer LO1 = 4*j2 + 1;
            localparam integer HI0 = 4*j2 + 2;
            localparam integer HI1 = 4*j2 + 3;
            assign sum0_L2[LO1:LO0] = sum0_L1[LO1:LO0];
            assign sum1_L2[LO1:LO0] = sum1_L1[LO1:LO0];
            assign sum0_L2[HI1:HI0] = carry0_L1[LOBLK] ? sum1_L1[HI1:HI0] : sum0_L1[HI1:HI0];
            assign sum1_L2[HI1:HI0] = carry1_L1[LOBLK] ? sum1_L1[HI1:HI0] : sum0_L1[HI1:HI0];
            assign carry0_L2[j2] = carry0_L1[LOBLK] ? carry1_L1[HIBLK] : carry0_L1[HIBLK];
            assign carry1_L2[j2] = carry1_L1[LOBLK] ? carry1_L1[HIBLK] : carry0_L1[HIBLK];
        end
    endgenerate

    // Level 3: combine size-4 blocks into size-8 blocks (2 blocks)
    wire [15:0] sum0_L3, sum1_L3;
    wire [1:0]  carry0_L3, carry1_L3;
    genvar j3;
    generate
        for (j3 = 0; j3 < 2; j3 = j3 + 1) begin : LVL3
            localparam integer LOBLK  = 2*j3;
            localparam integer HIBLK  = 2*j3 + 1;
            localparam integer LO_LSB = 8*j3;
            localparam integer LO_MSB = 8*j3 + 3;
            localparam integer HI_LSB = 8*j3 + 4;
            localparam integer HI_MSB = 8*j3 + 7;
            assign sum0_L3[LO_MSB:LO_LSB] = sum0_L2[LO_MSB:LO_LSB];
            assign sum1_L3[LO_MSB:LO_LSB] = sum1_L2[LO_MSB:LO_LSB];
            assign sum0_L3[HI_MSB:HI_LSB] = carry0_L2[LOBLK] ? sum1_L2[HI_MSB:HI_LSB] : sum0_L2[HI_MSB:HI_LSB];
            assign sum1_L3[HI_MSB:HI_LSB] = carry1_L2[LOBLK] ? sum1_L2[HI_MSB:HI_LSB] : sum0_L2[HI_MSB:HI_LSB];
            assign carry0_L3[j3] = carry0_L2[LOBLK] ? carry1_L2[HIBLK] : carry0_L2[HIBLK];
            assign carry1_L3[j3] = carry1_L2[LOBLK] ? carry1_L2[HIBLK] : carry0_L2[HIBLK];
        end
    endgenerate

    // Level 4: combine two size-8 blocks into the final 16-bit sum (overall carry-in = 0)
    wire [15:0] sum_final;
    assign sum_final[7:0]  = sum0_L3[7:0];
    assign sum_final[15:8] = carry0_L3[0] ? sum1_L3[15:8] : sum0_L3[15:8];

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum_final;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    wire [15:0] p, g;
    assign p = a_i ^ b_i;
    assign g = a_i & b_i;

    // Group 0: bits 3:0
    wire P0, G0;
    assign P0 = p[0] & p[1] & p[2] & p[3];
    assign G0 = g[3] | (p[3]&g[2]) | (p[3]&p[2]&g[1]) | (p[3]&p[2]&p[1]&g[0]);

    // Group 1: bits 7:4
    wire P1, G1;
    assign P1 = p[4] & p[5] & p[6] & p[7];
    assign G1 = g[7] | (p[7]&g[6]) | (p[7]&p[6]&g[5]) | (p[7]&p[6]&p[5]&g[4]);

    // Group 2: bits 11:8
    wire P2, G2;
    assign P2 = p[8] & p[9] & p[10] & p[11];
    assign G2 = g[11] | (p[11]&g[10]) | (p[11]&p[10]&g[9]) | (p[11]&p[10]&p[9]&g[8]);

    // Block carries (Cin overall = 0)
    wire C0, C1, C2, C3;
    assign C0 = 1'b0;
    assign C1 = G0;
    assign C2 = G1 | (P1 & G0);
    assign C3 = G2 | (P2 & G1) | (P2 & P1 & G0);

    // Group 0 internal carries (into bits 1,2,3)
    wire c0_0, c0_1, c0_2;
    assign c0_0 = g[0] | (p[0] & C0);
    assign c0_1 = g[1] | (p[1]&g[0]) | (p[1]&p[0]&C0);
    assign c0_2 = g[2] | (p[2]&g[1]) | (p[2]&p[1]&g[0]) | (p[2]&p[1]&p[0]&C0);

    // Group 1 internal carries (into bits 5,6,7)
    wire c1_0, c1_1, c1_2;
    assign c1_0 = g[4] | (p[4] & C1);
    assign c1_1 = g[5] | (p[5]&g[4]) | (p[5]&p[4]&C1);
    assign c1_2 = g[6] | (p[6]&g[5]) | (p[6]&p[5]&g[4]) | (p[6]&p[5]&p[4]&C1);

    // Group 2 internal carries (into bits 9,10,11)
    wire c2_0, c2_1, c2_2;
    assign c2_0 = g[8] | (p[8] & C2);
    assign c2_1 = g[9] | (p[9]&g[8]) | (p[9]&p[8]&C2);
    assign c2_2 = g[10] | (p[10]&g[9]) | (p[10]&p[9]&g[8]) | (p[10]&p[9]&p[8]&C2);

    // Group 3 internal carries (into bits 13,14,15)
    wire c3_0, c3_1, c3_2;
    assign c3_0 = g[12] | (p[12] & C3);
    assign c3_1 = g[13] | (p[13]&g[12]) | (p[13]&p[12]&C3);
    assign c3_2 = g[14] | (p[14]&g[13]) | (p[14]&p[13]&g[12]) | (p[14]&p[13]&p[12]&C3);

    // Sum bits
    wire [15:0] sum;
    assign sum[0]  = p[0];
    assign sum[1]  = p[1]  ^ c0_0;
    assign sum[2]  = p[2]  ^ c0_1;
    assign sum[3]  = p[3]  ^ c0_2;

    assign sum[4]  = p[4]  ^ C1;
    assign sum[5]  = p[5]  ^ c1_0;
    assign sum[6]  = p[6]  ^ c1_1;
    assign sum[7]  = p[7]  ^ c1_2;

    assign sum[8]  = p[8]  ^ C2;
    assign sum[9]  = p[9]  ^ c2_0;
    assign sum[10] = p[10] ^ c2_1;
    assign sum[11] = p[11] ^ c2_2;

    assign sum[12] = p[12] ^ C3;
    assign sum[13] = p[13] ^ c3_0;
    assign sum[14] = p[14] ^ c3_1;
    assign sum[15] = p[15] ^ c3_2;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    // Lower 8-bit add, carry-out extracted
    wire [8:0] sum_lo9;
    assign sum_lo9 = {1'b0, a_i[7:0]} + {1'b0, b_i[7:0]};

    // Upper 8-bit add speculated for both possible incoming carries
    wire [7:0] sum_hi_c0;
    wire [7:0] sum_hi_c1;
    assign sum_hi_c0 = a_i[15:8] + b_i[15:8];
    assign sum_hi_c1 = a_i[15:8] + b_i[15:8] + 8'd1;

    // Select correct upper result using the lower carry-out
    wire [7:0] sum_hi_sel;
    assign sum_hi_sel = sum_lo9[8] ? sum_hi_c1 : sum_hi_c0;

    wire [15:0] sum_final;
    assign sum_final = {sum_hi_sel, sum_lo9[7:0]};

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum_final;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    // ---- Leaf 4-bit blocks, each speculatively added for cin=0 and cin=1 ----
    wire [4:0] s0c0, s0c1; // bits[3:0]
    wire [4:0] s1c0, s1c1; // bits[7:4]
    wire [4:0] s2c0, s2c1; // bits[11:8]
    wire [4:0] s3c0, s3c1; // bits[15:12]

    assign s0c0 = {1'b0, a_i[3:0]}   + {1'b0, b_i[3:0]};
    assign s0c1 = {1'b0, a_i[3:0]}   + {1'b0, b_i[3:0]}   + 5'd1;

    assign s1c0 = {1'b0, a_i[7:4]}   + {1'b0, b_i[7:4]};
    assign s1c1 = {1'b0, a_i[7:4]}   + {1'b0, b_i[7:4]}   + 5'd1;

    assign s2c0 = {1'b0, a_i[11:8]}  + {1'b0, b_i[11:8]};
    assign s2c1 = {1'b0, a_i[11:8]}  + {1'b0, b_i[11:8]}  + 5'd1;

    assign s3c0 = {1'b0, a_i[15:12]} + {1'b0, b_i[15:12]};
    assign s3c1 = {1'b0, a_i[15:12]} + {1'b0, b_i[15:12]} + 5'd1;

    // ---- Level 1: merge leaf pairs into 8-bit blocks, keep both cin=0/cin=1 variants ----

    // block01 covers bits[7:0]
    wire c0_seg0 = s0c0[4];
    wire c1_seg0 = s0c1[4];

    wire [3:0] block01_sum_c0_low  = s0c0[3:0];
    wire [3:0] block01_sum_c0_high = c0_seg0 ? s1c1[3:0] : s1c0[3:0];
    wire       block01_carry_c0    = c0_seg0 ? s1c1[4]   : s1c0[4];

    wire [3:0] block01_sum_c1_low  = s0c1[3:0];
    wire [3:0] block01_sum_c1_high = c1_seg0 ? s1c1[3:0] : s1c0[3:0];
    // block01_carry_c1 not needed further (block01 is the low half of the final merge)

    // block23 covers bits[15:8] (bit positions relative to itself)
    wire c0_seg2 = s2c0[4];
    wire c1_seg2 = s2c1[4];

    wire [3:0] block23_sum_c0_low  = s2c0[3:0];
    wire [3:0] block23_sum_c0_high = c0_seg2 ? s3c1[3:0] : s3c0[3:0];

    wire [3:0] block23_sum_c1_low  = s2c1[3:0];
    wire [3:0] block23_sum_c1_high = c1_seg2 ? s3c1[3:0] : s3c0[3:0];

    // ---- Level 2: final merge (overall carry-in = 0), select block23 result using block01's real carry-out ----
    wire [7:0] finalLow  = {block01_sum_c0_high, block01_sum_c0_low};
    wire [7:0] finalHigh = block01_carry_c0 ? {block23_sum_c1_high, block23_sum_c1_low}
                                             : {block23_sum_c0_high, block23_sum_c0_low};

    wire [15:0] sum_final = {finalHigh, finalLow};

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum_final;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    wire [15:0] p, g;
    assign p = a_i ^ b_i;
    assign g = a_i & b_i;

    // c[i] = carry generated after adding bit i, with overall Cin = 0
    // c[i] = OR_{j=0..i} ( g[j] & AND_{k=j+1..i} p[k] )
    wire [14:0] c;

    genvar i, j;
    generate
        for (i = 0; i < 15; i = i + 1) begin : CROW
            wire [i:0] term;
            for (j = 0; j <= i; j = j + 1) begin : CCOL
                if (j == i) begin
                    assign term[j] = g[i];
                end else begin
                    assign term[j] = g[j] & (&p[i:j+1]);
                end
            end
            assign c[i] = |term;
        end
    endgenerate

    wire [15:0] sum;
    assign sum[0] = p[0];
    generate
        for (i = 1; i < 16; i = i + 1) begin : SUMBIT
            assign sum[i] = p[i] ^ c[i-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    // Bit-level generate/propagate
    wire [15:0] p0, g0;
    assign p0 = a_i ^ b_i;
    assign g0 = a_i & b_i;

    genvar i;

    // ---- Stage 1: ss=0, block size 2 ----
    // Upper half (odd i) merges with boundary J = i-1
    wire [15:0] G1, P1;
    generate
        for (i = 0; i < 16; i = i + 1) begin : ST1
            if (((i >> 0) & 1) == 1) begin : MERGE
                localparam integer J = (((i >> 0) << 0) - 1);
                assign G1[i] = g0[i] | (p0[i] & g0[J]);
                assign P1[i] = p0[i] & p0[J];
            end else begin : PASS
                assign G1[i] = g0[i];
                assign P1[i] = p0[i];
            end
        end
    endgenerate

    // ---- Stage 2: ss=1, block size 4 ----
    wire [15:0] G2, P2;
    generate
        for (i = 0; i < 16; i = i + 1) begin : ST2
            if (((i >> 1) & 1) == 1) begin : MERGE
                localparam integer J = (((i >> 1) << 1) - 1);
                assign G2[i] = G1[i] | (P1[i] & G1[J]);
                assign P2[i] = P1[i] & P1[J];
            end else begin : PASS
                assign G2[i] = G1[i];
                assign P2[i] = P1[i];
            end
        end
    endgenerate

    // ---- Stage 3: ss=2, block size 8 ----
    wire [15:0] G3, P3;
    generate
        for (i = 0; i < 16; i = i + 1) begin : ST3
            if (((i >> 2) & 1) == 1) begin : MERGE
                localparam integer J = (((i >> 2) << 2) - 1);
                assign G3[i] = G2[i] | (P2[i] & G2[J]);
                assign P3[i] = P2[i] & P2[J];
            end else begin : PASS
                assign G3[i] = G2[i];
                assign P3[i] = P2[i];
            end
        end
    endgenerate

    // ---- Stage 4: ss=3, block size 16 ----
    wire [15:0] G4, P4;
    generate
        for (i = 0; i < 16; i = i + 1) begin : ST4
            if (((i >> 3) & 1) == 1) begin : MERGE
                localparam integer J = (((i >> 3) << 3) - 1);
                assign G4[i] = G3[i] | (P3[i] & G3[J]);
                assign P4[i] = P3[i] & P3[J];
            end else begin : PASS
                assign G4[i] = G3[i];
                assign P4[i] = P3[i];
            end
        end
    endgenerate

    // Carry into bit i+1 (overall carry-in = 0)
    wire [15:0] c = G4;

    // Final sum bits
    wire [15:0] sum;
    assign sum[0] = p0[0];
    generate
        for (i = 1; i < 16; i = i + 1) begin : SUMB
            assign sum[i] = p0[i] ^ c[i-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
