    output reg  [15:0] y_o
);

    wire [15:0] p0, g0;
    assign p0 = a_i ^ b_i;
    assign g0 = a_i & b_i;

    genvar i;

    // ---- Stage 1: distance 1, pre-merge odd bit with its even neighbor ----
    wire [15:0] P1, G1;
    generate
        for (i = 0; i < 16; i = i + 1) begin : ST1
            if ((i % 2) == 1) begin : ODD
                assign G1[i] = g0[i] | (p0[i] & g0[i-1]);
                assign P1[i] = p0[i] & p0[i-1];
            end else begin : EVP
                assign G1[i] = g0[i];
                assign P1[i] = p0[i];
            end
        end
    endgenerate

    // ---- Stage 2: distance 2, update only odd i>=3 (deep network on odd lane) ----
    wire [15:0] P2, G2;
    generate
        for (i = 0; i < 16; i = i + 1) begin : ST2
            if (((i % 2) == 1) && (i >= 3)) begin : UPD
                assign G2[i] = G1[i] | (P1[i] & G1[i-2]);
                assign P2[i] = P1[i] & P1[i-2];
            end else begin : PASS
                assign G2[i] = G1[i];
                assign P2[i] = P1[i];
            end
        end
    endgenerate

    // ---- Stage 3: distance 4, update only odd i>=5 ----
    wire [15:0] P3, G3;
    generate
        for (i = 0; i < 16; i = i + 1) begin : ST3
            if (((i % 2) == 1) && (i >= 5)) begin : UPD
                assign G3[i] = G2[i] | (P2[i] & G2[i-4]);
                assign P3[i] = P2[i] & P2[i-4];
            end else begin : PASS
                assign G3[i] = G2[i];
                assign P3[i] = P2[i];
            end
        end
    endgenerate

    // ---- Stage 4: distance 8, update only odd i>=9 ----
    wire [15:0] P4, G4;
    generate
        for (i = 0; i < 16; i = i + 1) begin : ST4
            if (((i % 2) == 1) && (i >= 9)) begin : UPD
                assign G4[i] = G3[i] | (P3[i] & G3[i-8]);
                assign P4[i] = P3[i] & P3[i-8];
            end else begin : PASS
                assign G4[i] = G3[i];
                assign P4[i] = P3[i];
            end
        end
    endgenerate

    // ---- Final carry array: odd bits already final after stage4; even bits need
    //      one more OR-merge with the previous (odd) lane's final carry ----
    wire [15:0] c;
    assign c[0] = g0[0];
    generate
        for (i = 1; i < 16; i = i + 1) begin : CARRY
            if ((i % 2) == 1) begin : ODDC
                assign c[i] = G4[i];
            end else begin : EVENC
                assign c[i] = G1[i] | (P1[i] & c[i-1]);
            end
        end
    endgenerate

    // ---- Sum bits ----
    wire [15:0] sum;
    assign sum[0] = p0[0];
    generate
        for (i = 1; i < 16; i = i + 1) begin : SUMB
            assign sum[i] = p0[i] ^ c[i-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    wire [15:0] p0, g0;
    assign p0 = a_i ^ b_i;
    assign g0 = a_i & b_i;

    // ---- Up-sweep stage 1 (d=1): nodes 1,3,5,7,9,11,13,15 ----
    wire G1_1,P1_1, G1_3,P1_3, G1_5,P1_5, G1_7,P1_7;
    wire G1_9,P1_9, G1_11,P1_11, G1_13,P1_13, G1_15,P1_15;

    assign G1_1  = g0[1]  | (p0[1]  & g0[0]);
    assign P1_1  = p0[1]  & p0[0];
    assign G1_3  = g0[3]  | (p0[3]  & g0[2]);
    assign P1_3  = p0[3]  & p0[2];
    assign G1_5  = g0[5]  | (p0[5]  & g0[4]);
    assign P1_5  = p0[5]  & p0[4];
    assign G1_7  = g0[7]  | (p0[7]  & g0[6]);
    assign P1_7  = p0[7]  & p0[6];
    assign G1_9  = g0[9]  | (p0[9]  & g0[8]);
    assign P1_9  = p0[9]  & p0[8];
    assign G1_11 = g0[11] | (p0[11] & g0[10]);
    assign P1_11 = p0[11] & p0[10];
    assign G1_13 = g0[13] | (p0[13] & g0[12]);
    assign P1_13 = p0[13] & p0[12];
    assign G1_15 = g0[15] | (p0[15] & g0[14]);
    assign P1_15 = p0[15] & p0[14];

    // ---- Up-sweep stage 2 (d=2): nodes 3,7,11,15 ----
    wire G2_3,P2_3, G2_7,P2_7, G2_11,P2_11, G2_15,P2_15;

    assign G2_3  = G1_3  | (P1_3  & G1_1);
    assign P2_3  = P1_3  & P1_1;
    assign G2_7  = G1_7  | (P1_7  & G1_5);
    assign P2_7  = P1_7  & P1_5;
    assign G2_11 = G1_11 | (P1_11 & G1_9);
    assign P2_11 = P1_11 & P1_9;
    assign G2_15 = G1_15 | (P1_15 & G1_13);
    assign P2_15 = P1_15 & P1_13;

    // ---- Up-sweep stage 3 (d=4): nodes 7,15 ----
    wire G3_7,P3_7, G3_15,P3_15;

    assign G3_7  = G2_7  | (P2_7  & G2_3);
    assign P3_7  = P2_7  & P2_3;
    assign G3_15 = G2_15 | (P2_15 & G2_11);
    assign P3_15 = P2_15 & P2_11;

    // ---- Up-sweep stage 4 (d=8): node 15 (final overall carry, unused for sum) ----
    wire G4_15, P4_15;
    assign G4_15 = G3_15 | (P3_15 & G3_7);
    assign P4_15 = P3_15 & P3_7;

    // ---- Down-sweep d=4: node 11 ----
    wire Gd_11, Pd_11;
    assign Gd_11 = G2_11 | (P2_11 & G3_7);
    assign Pd_11 = P2_11 & P3_7;

    // ---- Down-sweep d=2: nodes 5,9,13 ----
    wire Gd_5,Pd_5, Gd_9,Pd_9, Gd_13,Pd_13;

    assign Gd_5  = G1_5  | (P1_5  & G2_3);
    assign Pd_5  = P1_5  & P2_3;
    assign Gd_9  = G1_9  | (P1_9  & G3_7);
    assign Pd_9  = P1_9  & P3_7;
    assign Gd_13 = G1_13 | (P1_13 & Gd_11);
    assign Pd_13 = P1_13 & Pd_11;

    // ---- Down-sweep d=1: nodes 2,4,6,8,10,12,14 ----
    wire Gd_2,Pd_2, Gd_4,Pd_4, Gd_6,Pd_6, Gd_8,Pd_8;
    wire Gd_10,Pd_10, Gd_12,Pd_12, Gd_14,Pd_14;

    assign Gd_2  = g0[2]  | (p0[2]  & G1_1);
    assign Pd_2  = p0[2]  & P1_1;
    assign Gd_4  = g0[4]  | (p0[4]  & G2_3);
    assign Pd_4  = p0[4]  & P2_3;
    assign Gd_6  = g0[6]  | (p0[6]  & Gd_5);
    assign Pd_6  = p0[6]  & Pd_5;
    assign Gd_8  = g0[8]  | (p0[8]  & G3_7);
    assign Pd_8  = p0[8]  & P3_7;
    assign Gd_10 = g0[10] | (p0[10] & Gd_9);
    assign Pd_10 = p0[10] & Pd_9;
    assign Gd_12 = g0[12] | (p0[12] & Gd_11);
    assign Pd_12 = p0[12] & Pd_11;
    assign Gd_14 = g0[14] | (p0[14] & Gd_13);
    assign Pd_14 = p0[14] & Pd_13;

    // ---- Carries into each bit (overall cin = 0) ----
    wire [14:0] c;
    assign c[0]  = g0[0];
    assign c[1]  = G1_1;
    assign c[2]  = Gd_2;
    assign c[3]  = G2_3;
    assign c[4]  = Gd_4;
    assign c[5]  = Gd_5;
    assign c[6]  = Gd_6;
    assign c[7]  = G3_7;
    assign c[8]  = Gd_8;
    assign c[9]  = Gd_9;
    assign c[10] = Gd_10;
    assign c[11] = Gd_11;
    assign c[12] = Gd_12;
    assign c[13] = Gd_13;
    assign c[14] = Gd_14;

    // ---- Sum bits ----
    wire [15:0] sum;
    assign sum[0]  = p0[0];
    assign sum[1]  = p0[1]  ^ c[0];
    assign sum[2]  = p0[2]  ^ c[1];
    assign sum[3]  = p0[3]  ^ c[2];
    assign sum[4]  = p0[4]  ^ c[3];
    assign sum[5]  = p0[5]  ^ c[4];
    assign sum[6]  = p0[6]  ^ c[5];
    assign sum[7]  = p0[7]  ^ c[6];
    assign sum[8]  = p0[8]  ^ c[7];
    assign sum[9]  = p0[9]  ^ c[8];
    assign sum[10] = p0[10] ^ c[9];
    assign sum[11] = p0[11] ^ c[10];
    assign sum[12] = p0[12] ^ c[11];
    assign sum[13] = p0[13] ^ c[12];
    assign sum[14] = p0[14] ^ c[13];
    assign sum[15] = p0[15] ^ c[14];

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    wire [15:0] p, g;
    assign p = a_i ^ b_i;
    assign g = a_i & b_i;

    // ---------------- Group 0: bits 3:0, Cin = 0 ----------------
    wire c0_1, c0_2, c0_3;
    assign c0_1 = g[0] | (p[0] & 1'b0);
    assign c0_2 = g[1] | (p[1] & c0_1);
    assign c0_3 = g[2] | (p[2] & c0_2);

    wire G0, P0, Cout0;
    assign G0 = g[3] | (p[3]&g[2]) | (p[3]&p[2]&g[1]) | (p[3]&p[2]&p[1]&g[0]);
    assign P0 = p[0] & p[1] & p[2] & p[3];
    assign Cout0 = G0; // P0 & Cin(=0) is 0

    wire [15:0] sum;
    assign sum[0] = p[0] ^ 1'b0;
    assign sum[1] = p[1] ^ c0_1;
    assign sum[2] = p[2] ^ c0_2;
    assign sum[3] = p[3] ^ c0_3;

    // ---------------- Group 1: bits 7:4, Cin = Cout0 ----------------
    wire c1_1, c1_2, c1_3;
    assign c1_1 = g[4] | (p[4] & Cout0);
    assign c1_2 = g[5] | (p[5] & c1_1);
    assign c1_3 = g[6] | (p[6] & c1_2);

    wire G1, P1, Cout1;
    assign G1 = g[7] | (p[7]&g[6]) | (p[7]&p[6]&g[5]) | (p[7]&p[6]&p[5]&g[4]);
    assign P1 = p[4] & p[5] & p[6] & p[7];
    assign Cout1 = G1 | (P1 & Cout0);

    assign sum[4] = p[4] ^ Cout0;
    assign sum[5] = p[5] ^ c1_1;
    assign sum[6] = p[6] ^ c1_2;
    assign sum[7] = p[7] ^ c1_3;

    // ---------------- Group 2: bits 11:8, Cin = Cout1 ----------------
    wire c2_1, c2_2, c2_3;
    assign c2_1 = g[8] | (p[8] & Cout1);
    assign c2_2 = g[9] | (p[9] & c2_1);
    assign c2_3 = g[10] | (p[10] & c2_2);

    wire G2, P2, Cout2;
    assign G2 = g[11] | (p[11]&g[10]) | (p[11]&p[10]&g[9]) | (p[11]&p[10]&p[9]&g[8]);
    assign P2 = p[8] & p[9] & p[10] & p[11];
    assign Cout2 = G2 | (P2 & Cout1);

    assign sum[8]  = p[8]  ^ Cout1;
    assign sum[9]  = p[9]  ^ c2_1;
    assign sum[10] = p[10] ^ c2_2;
    assign sum[11] = p[11] ^ c2_3;

    // ---------------- Group 3: bits 15:12, Cin = Cout2 ----------------
    wire c3_1, c3_2, c3_3;
    assign c3_1 = g[12] | (p[12] & Cout2);
    assign c3_2 = g[13] | (p[13] & c3_1);
    assign c3_3 = g[14] | (p[14] & c3_2);

    assign sum[12] = p[12] ^ Cout2;
    assign sum[13] = p[13] ^ c3_1;
    assign sum[14] = p[14] ^ c3_2;
    assign sum[15] = p[15] ^ c3_3;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    wire [15:0] p, g;
    assign p = a_i ^ b_i;
    assign g = a_i & b_i;

    wire [15:0] sum;

    // ---------------- Group 0: bits 4:0 (size 5), Cin = 0 ----------------
    wire c0_0, c0_1, c0_2, c0_3;
    assign c0_0 = g[0];                      // p[0]&0 term dropped
    assign c0_1 = g[1] | (p[1] & c0_0);
    assign c0_2 = g[2] | (p[2] & c0_1);
    assign c0_3 = g[3] | (p[3] & c0_2);

    assign sum[0] = p[0];
    assign sum[1] = p[1] ^ c0_0;
    assign sum[2] = p[2] ^ c0_1;
    assign sum[3] = p[3] ^ c0_2;
    assign sum[4] = p[4] ^ c0_3;

    wire G0, P0, Cout0;
    assign G0 = g[4] | (p[4]&g[3]) | (p[4]&p[3]&g[2]) | (p[4]&p[3]&p[2]&g[1]) |
                (p[4]&p[3]&p[2]&p[1]&g[0]);
    assign P0 = p[0]&p[1]&p[2]&p[3]&p[4];
    assign Cout0 = G0; // Cin0 = 0, so P0&Cin0 term = 0

    // ---------------- Group 1: bits 9:5 (size 5), Cin = Cout0 ----------------
    wire c1_0, c1_1, c1_2, c1_3;
    assign c1_0 = g[5] | (p[5] & Cout0);
    assign c1_1 = g[6] | (p[6] & c1_0);
    assign c1_2 = g[7] | (p[7] & c1_1);
    assign c1_3 = g[8] | (p[8] & c1_2);

    assign sum[5] = p[5] ^ Cout0;
    assign sum[6] = p[6] ^ c1_0;
    assign sum[7] = p[7] ^ c1_1;
    assign sum[8] = p[8] ^ c1_2;
    assign sum[9] = p[9] ^ c1_3;

    wire G1, P1, Cout1;
    assign G1 = g[9] | (p[9]&g[8]) | (p[9]&p[8]&g[7]) | (p[9]&p[8]&p[7]&g[6]) |
                (p[9]&p[8]&p[7]&p[6]&g[5]);
    assign P1 = p[5]&p[6]&p[7]&p[8]&p[9];
    assign Cout1 = G1 | (P1 & Cout0);

    // ---------------- Group 2: bits 13:10 (size 4), Cin = Cout1 ----------------
    wire c2_0, c2_1, c2_2;
    assign c2_0 = g[10] | (p[10] & Cout1);
    assign c2_1 = g[11] | (p[11] & c2_0);
    assign c2_2 = g[12] | (p[12] & c2_1);

    assign sum[10] = p[10] ^ Cout1;
    assign sum[11] = p[11] ^ c2_0;
    assign sum[12] = p[12] ^ c2_1;
    assign sum[13] = p[13] ^ c2_2;

    wire G2, P2, Cout2;
    assign G2 = g[13] | (p[13]&g[12]) | (p[13]&p[12]&g[11]) | (p[13]&p[12]&p[11]&g[10]);
    assign P2 = p[10]&p[11]&p[12]&p[13];
    assign Cout2 = G2 | (P2 & Cout1);

    // ---------------- Group 3: bits 15:14 (size 2), Cin = Cout2 (tail, kept short) ----------------
    wire c3_0;
    assign c3_0 = g[14] | (p[14] & Cout2);

    assign sum[14] = p[14] ^ Cout2;
    assign sum[15] = p[15] ^ c3_0;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum;
        end
    end

endmodule

module addpipe16 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [15:0] a_i,
    input  wire [15:0] b_i,
    output reg          valid_o,
    output reg  [15:0] y_o
);

    wire [15:0] p0, g0;
    assign p0 = a_i ^ b_i;
    assign g0 = a_i & b_i;

    // ---- Ripple prefix for bits 0,1,2 (Cin overall = 0) ----
    wire c0, c1, c2;
    assign c0 = g0[0];
    assign c1 = g0[1] | (p0[1] & c0);
    assign c2 = g0[2] | (p0[2] & c1);

    // ---- Local p/g for the upper 13-bit group (bits 3..15), local index k=0..12 ----
    wire [12:0] pl, gl;
    genvar k;
    generate
        for (k = 0; k < 13; k = k + 1) begin : LOCALPG
            assign pl[k] = p0[k+3];
            assign gl[k] = g0[k+3];
        end
    endgenerate

    // ---- Sklansky prefix tree over the 13-bit group, assuming internal Cin=0 ----
    wire [12:0] G1, P1, G2, P2, G3, P3, G4, P4;

    generate
        for (k = 0; k < 13; k = k + 1) begin : ST1
            if (((k >> 0) & 1) == 1) begin : MERGE
                localparam integer J = (((k >> 0) << 0) - 1);
                assign G1[k] = gl[k] | (pl[k] & gl[J]);
                assign P1[k] = pl[k] & pl[J];
            end else begin : PASS
                assign G1[k] = gl[k];
                assign P1[k] = pl[k];
            end
        end
    endgenerate

    generate
        for (k = 0; k < 13; k = k + 1) begin : ST2
            if (((k >> 1) & 1) == 1) begin : MERGE
                localparam integer J = (((k >> 1) << 1) - 1);
                assign G2[k] = G1[k] | (P1[k] & G1[J]);
                assign P2[k] = P1[k] & P1[J];
            end else begin : PASS
                assign G2[k] = G1[k];
                assign P2[k] = P1[k];
            end
        end
    endgenerate

    generate
        for (k = 0; k < 13; k = k + 1) begin : ST3
            if (((k >> 2) & 1) == 1) begin : MERGE
                localparam integer J = (((k >> 2) << 2) - 1);
                assign G3[k] = G2[k] | (P2[k] & G2[J]);
                assign P3[k] = P2[k] & P2[J];
            end else begin : PASS
                assign G3[k] = G2[k];
                assign P3[k] = P2[k];
            end
        end
    endgenerate

    generate
        for (k = 0; k < 13; k = k + 1) begin : ST4
            if (((k >> 3) & 1) == 1) begin : MERGE
                localparam integer J = (((k >> 3) << 3) - 1);
                assign G4[k] = G3[k] | (P3[k] & G3[J]);
                assign P4[k] = P3[k] & P3[J];
            end else begin : PASS
                assign G4[k] = G3[k];
                assign P4[k] = P3[k];
            end
        end
    endgenerate

    // ---- Inject the ripple carry c2 into the local-group prefix results ----
    wire [12:0] Ctotal;
    assign Ctotal = G4 | (P4 & {13{c2}});

    // ---- Final sum ----
    wire [15:0] sum;
    assign sum[0] = p0[0];
    assign sum[1] = p0[1] ^ c0;
    assign sum[2] = p0[2] ^ c1;
    assign sum[3] = p0[3] ^ c2;

    genvar i;
    generate
        for (i = 4; i < 16; i = i + 1) begin : SUMB
            assign sum[i] = p0[i] ^ Ctotal[i-4];
        end
    endgenerate

    always @(posedge clk) begin
        if (!rst_n) begin
            valid_o <= 1'b0;
            y_o     <= 16'd0;
        end else begin
            valid_o <= valid_i;

            if (valid_i)
                y_o <= sum;
        end
    end

endmodule
